import { AVATAR_COLORS } from "./colors.js";
import type { CharacterComponents } from "./types.js";

/**
 * The white of an eye: ice white rather than paper white, so the eyes read as
 * part of the frost the characters are cut from. Exported because a consumer
 * that reduces an eye pair to a silhouette (an Android themed-icon mask, say)
 * has to tell the sclera paths from the pupils, and matching on this is the
 * only way to do that from the path list alone.
 */
export const SCLERA = "#F4F8FD";
/** Pupils are deep night blue rather than black, the darkest colour in the ANU palette. */
const PUPIL = "#0F1C38";

/**
 * Every body shape, eye style, and face-centre override an avatar can be
 * composed from, plus the palette re-exposed on `colors`.
 *
 * This is the single definition. The daemon serves it over
 * `/avatar/character-components`; clients that must compose an avatar before
 * the daemon answers (a hatching screen, a chooser card) import it directly
 * so no copy has to be kept in step with this one.
 *
 * The characters are ANU's "frostlings": crystal and frost spirits built from
 * hexagons, shards and facets. Ids are persisted in every workspace's avatar
 * manifest and baked into app icon names, so they predate these designs and
 * stay as they are; what a user sees for each id is in `./labels.ts`.
 *
 * All geometry is absolute `M`/`L`/`C`/`Z` path data, so every number in
 * a path is half of an x,y pair (the web body wobble relies on that). Bodies
 * are tight to their viewBox; every eye style shares a 600x600 source box
 * centred on (300, 300), so a pair lands on a body at a scale set by the
 * body's shorter side.
 */
